func (q *Queries) UpsertReportScore(ctx context.Context, arg UpsertReportScoreParams) (ReportScore, error) {
	row := q.db.QueryRow(ctx, upsertReportScore,
		arg.TenantID,
		arg.AcademicYearID,
		arg.TermID,
		arg.ClassID,
		arg.SubjectID,
		arg.StudentUserID,
		arg.PreviousScore,
		arg.ManualScore,
		arg.AutomaticScore,
	)
	var i ReportScore
	err := row.Scan(
		&i.ID,
		&i.TenantID,
		&i.AcademicYearID,
		&i.TermID,
		&i.ClassID,
		&i.SubjectID,
		&i.StudentUserID,
		&i.PreviousScore,
		&i.ManualScore,
		&i.FinalScore,
		&i.ComputedAt,
		&i.AutomaticScore,
	)
	return i, err
}

const upsertTPMapping = `-- name: UpsertTPMapping :one
insert into report_tp_mappings (tenant_id, component_id, export_code, r_min, r_max, t_min, t_max)
values ($1, $2, $3, $4, $5, $6, $7)
on conflict (component_id) do update set export_code = excluded.export_code, r_min = excluded.r_min, r_max = excluded.r_max, t_min = excluded.t_min, t_max = excluded.t_max
returning id, tenant_id, component_id, export_code, r_min, r_max, t_min, t_max
`

type UpsertTPMappingParams struct {
	TenantID    uuid.UUID      `json:"tenant_id"`
	ComponentID uuid.UUID      `json:"component_id"`
	ExportCode  string         `json:"export_code"`
	RMin        pgtype.Numeric `json:"r_min"`
	RMax        pgtype.Numeric `json:"r_max"`
	TMin        pgtype.Numeric `json:"t_min"`
	TMax        pgtype.Numeric `json:"t_max"`
}

func (q *Queries) UpsertTPMapping(ctx context.Context, arg UpsertTPMappingParams) (ReportTpMapping, error) {
	row := q.db.QueryRow(ctx, upsertTPMapping,
		arg.TenantID,
		arg.ComponentID,
		arg.ExportCode,
		arg.RMin,
		arg.RMax,
		arg.TMin,
		arg.TMax,
	)
	var i ReportTpMapping
	err := row.Scan(
		&i.ID,
		&i.TenantID,
		&i.ComponentID,
		&i.ExportCode,
		&i.RMin,
		&i.RMax,
		&i.TMin,
		&i.TMax,
	)
	return i, err
}

const visibleStarBalance = `-- name: VisibleStarBalance :one
select coalesce(sum(delta), 0)::int as balance from star_events
where tenant_id = $1 and academic_year_id = $2 and student_user_id = $3 and visible_to_student
`

type VisibleStarBalanceParams struct {
	TenantID       uuid.UUID `json:"tenant_id"`
	AcademicYearID uuid.UUID `json:"academic_year_id"`
	StudentUserID  uuid.UUID `json:"student_user_id"`
}

// The balance a student (or MyGrades) may see: events the teacher marked
// visible_to_student only (grading_extended.go:653's "AND
// e.visible_to_student=TRUE"). Hidden adjustments still count toward the
// real (StarBalance) total a teacher works from.
func (q *Queries) VisibleStarBalance(ctx context.Context, arg VisibleStarBalanceParams) (int32, error) {
	row := q.db.QueryRow(ctx, visibleStarBalance, arg.TenantID, arg.AcademicYearID, arg.StudentUserID)
	var balance int32
	err := row.Scan(&balance)
	return balance, err
}
